INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES (0, 1, 10, 104411, 1, "そろそろ野営の準備を始めねばな。\n食料は現地調達するしかないが、\n獣を狩るか、野草を採るか……", 11, 20132, 1201320005, 0, 0);
INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES ("", "", "", 0, "", "", 91, 20132, 1201320006, "", "");
