INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES (0, 1, 10, 101611, 1, "ねねね！\nみんなで記念撮影しよ？\nあとで見返したら絶対エモいっしょ！", 11, 20162, 1201620005, 0, 0);
INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES ("", "", "", 0, "", "", 91, 20162, 1201620006, "", "");
