INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES ("", "", 0, "vo_travel_talk", 0, "vo_travel_talk_20018_01", 21, 20182, 1201820007, "", "");
INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES (0, 1, 10, 118011, 1, "陛下直々のご命令とあれば、\nこのクレジッタ・キャッシュ！\nご満足いただける大秘宝を、\nなんとしても手に入れてみせますわ！", 11, 20182, 1201820008, 0, 0);
INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES ("", "", "", 0, "", "", 91, 20182, 1201820009, "", "");
